const fs = require('fs');
const path = require('path');
const vm = require('vm');

function emit(obj) {
  process.stdout.write(JSON.stringify(obj));
}

function norm(s) {
  return String(s == null ? '' : s).replace(/[\u2018\u2019]/g, "'").replace(/\s+/g, ' ').trim().toLowerCase();
}

const LABEL_KEYS = {};
LABEL_KEYS[norm('What\u2019s the Job Title?')] = 'job_title';
LABEL_KEYS[norm('Company Name?')] = 'company_name';
LABEL_KEYS[norm('Link the Job Description here:')] = 'job_link';
LABEL_KEYS[norm('Tone')] = 'tone';
LABEL_KEYS[norm('Use Emojis?')] = 'use_emojis';

const TEXT_KEYS = ['job_title', 'company_name', 'job_link', 'tone'];

function runCase(linkedom, html, js, inp) {
  const parsed = linkedom.parseHTML(html);
  const window = parsed.window;
  const document = parsed.document;

  const fields = {};
  const labels = Array.from(document.querySelectorAll('label'));
  for (const lab of labels) {
    const key = LABEL_KEYS[norm(lab.textContent)];
    if (!key) continue;
    let el = null;
    const forId = lab.getAttribute('for');
    if (forId) el = document.getElementById(forId);
    if (!el) el = lab.querySelector('input,textarea,select');
    if (el) fields[key] = el;
  }
  const needed = TEXT_KEYS.concat(['use_emojis']);
  for (const k of needed) {
    if (!fields[k]) throw new Error('field not found for label: ' + k);
  }

  for (const k of TEXT_KEYS) {
    fields[k].value = inp[k] == null ? '' : String(inp[k]);
  }
  fields.use_emojis.checked = !!inp.use_emojis;

  let btn = Array.from(document.querySelectorAll('button')).find(b => norm(b.textContent) === 'submit');
  if (!btn) btn = document.getElementById('submit-button');
  if (!btn) btn = document.querySelector('input[type=submit]');
  if (!btn) throw new Error('submit button not found');

  const noop = function () {};
  const silentConsole = { log: noop, warn: noop, error: noop, info: noop, debug: noop };
  const EvCtor = window.Event || globalThis.Event;
  const ctx = vm.createContext({
    window: window,
    document: document,
    console: silentConsole,
    Event: EvCtor,
    CustomEvent: window.CustomEvent || globalThis.CustomEvent
  });

  vm.runInContext(js, ctx, { timeout: 2000, filename: 'block-2.txt' });

  btn.dispatchEvent(new EvCtor('click', { bubbles: true, cancelable: true }));

  const out = document.getElementById('output-text') || document.querySelector('textarea') || document.querySelector('output');
  if (!out) throw new Error('output field not found');
  const actual = typeof out.value === 'string' ? out.value : out.textContent;
  if (typeof actual !== 'string') throw new Error('output value is not a string');
  return actual;
}

function main() {
  let linkedom, inputs, html, js;
  try {
    linkedom = require('linkedom');
    inputs = JSON.parse(fs.readFileSync(path.join(__dirname, 'inputs.json'), 'utf8'));
    html = fs.readFileSync(path.join(__dirname, 'block-0.txt'), 'utf8');
    js = fs.readFileSync(path.join(__dirname, 'block-2.txt'), 'utf8');
  } catch (e) {
    emit({ results: [], harness_error: 'setup failed: ' + String((e && e.message) || e) });
    return;
  }
  if (!Array.isArray(inputs)) {
    emit({ results: [], harness_error: 'inputs.json is not an array' });
    return;
  }

  const results = [];
  for (const item of inputs) {
    const id = item && item.id;
    try {
      const actual = runCase(linkedom, html, js, (item && item.input) || {});
      results.push({ id: id, actual: actual });
    } catch (e) {
      results.push({ id: id, error: String((e && e.message) || e) });
    }
  }
  emit({ results: results });
}

main();

const fs = require('fs');
const path = require('path');
const vm = require('vm');

function emit(obj) { process.stdout.write(JSON.stringify(obj)); }

const CURLY = String.fromCharCode(8217);
const SQ = String.fromCharCode(39);
const LABELS = {
  job_title: 'What' + CURLY + 's the Job Title?',
  company_name: 'Company Name?',
  job_link: 'Link the Job Description here:',
  tone: 'Tone',
  use_emojis: 'Use Emojis?'
};

function squash(s) { return String(s).replace(/\s+/g, ' ').trim(); }
function fold(s) { return squash(s).split(CURLY).join(SQ); }

function findControl(doc, text) {
  const labels = Array.from(doc.querySelectorAll('label'));
  let lab = labels.find(l => squash(l.textContent) === text);
  if (!lab) lab = labels.find(l => fold(l.textContent) === fold(text));
  if (!lab) return null;
  const forId = lab.getAttribute('for');
  if (forId) return doc.getElementById(forId);
  return lab.querySelector('input, select, textarea');
}

function fire(el, type) {
  const W = el.ownerDocument.defaultView;
  const Ctor = (W && W.Event) || Event;
  el.dispatchEvent(new Ctor(type, { bubbles: true, cancelable: true }));
}

function setField(doc, key, value) {
  const label = LABELS[key];
  const ctl = findControl(doc, label);
  if (!ctl) throw new Error('control not found for label: ' + label);
  const tag = ctl.tagName.toUpperCase();
  const type = String(ctl.getAttribute('type') || '').toLowerCase();
  if (tag === 'INPUT' && type === 'checkbox') { ctl.checked = Boolean(value); return; }
  if (tag === 'SELECT') {
    Array.from(ctl.querySelectorAll('option')).forEach(o => {
      const v = o.getAttribute('value');
      o.selected = (v !== null ? v : squash(o.textContent)) === String(value);
    });
  }
  ctl.value = String(value);
  try { fire(ctl, 'input'); fire(ctl, 'change'); } catch (e) { /* optional events */ }
}

function findSubmit(doc) {
  return Array.from(doc.querySelectorAll('button, input')).find(b => {
    const t = b.tagName.toUpperCase();
    const ty = String(b.getAttribute('type') || '').toLowerCase();
    return (t === 'BUTTON' && (ty === '' || ty === 'submit')) || (t === 'INPUT' && ty === 'submit');
  }) || null;
}

function readOutput(doc) {
  const areas = Array.from(doc.querySelectorAll('textarea'));
  let el = areas.find(t => t.getAttribute('id') === 'output') || areas[0] || null;
  if (!el) el = Array.from(doc.querySelectorAll('input')).find(i => i.hasAttribute('readonly')) || null;
  if (!el) el = doc.getElementById('output');
  if (!el) throw new Error('output field not found');
  const tag = el.tagName.toUpperCase();
  if ((tag === 'TEXTAREA' || tag === 'INPUT') && typeof el.value === 'string') return el.value;
  return el.textContent;
}

function runCase(linkedom, js, page, input) {
  const parsed = linkedom.parseHTML(page);
  const doc = parsed.document;
  const W = parsed.window || doc.defaultView;
  const logs = [];
  const sink = (...a) => { logs.push(a); };
  const ctx = vm.createContext({
    document: doc,
    window: W,
    console: { log: sink, info: sink, warn: sink, error: sink, debug: sink },
    setTimeout: () => 0,
    clearTimeout: () => {},
    setInterval: () => 0,
    clearInterval: () => {}
  });
  vm.runInContext(js, ctx, { filename: 'script.js', timeout: 3000 });

  const form = doc.getElementById('outreach-form') || doc.querySelector('form');
  if (!form) throw new Error('form not found');
  const btn = findSubmit(doc);
  if (!btn) throw new Error('submit button not found');

  let submitted = false;
  form.addEventListener('submit', () => { submitted = true; });

  setField(doc, 'job_title', input.job_title ?? '');
  setField(doc, 'company_name', input.company_name ?? '');
  setField(doc, 'job_link', input.job_link ?? '');
  setField(doc, 'tone', input.tone ?? '');
  setField(doc, 'use_emojis', Boolean(input.use_emojis));

  fire(btn, 'click');
  if (!submitted) fire(form, 'submit');

  return readOutput(doc);
}

function main() {
  let inputs, html, css, js, linkedom;
  try {
    const dir = process.cwd();
    inputs = JSON.parse(fs.readFileSync(path.join(dir, 'inputs.json'), 'utf8'));
    if (!Array.isArray(inputs)) throw new Error('inputs.json must be an array');
    html = fs.readFileSync(path.join(dir, 'block-0.txt'), 'utf8');
    css = fs.readFileSync(path.join(dir, 'block-1.txt'), 'utf8');
    js = fs.readFileSync(path.join(dir, 'block-2.txt'), 'utf8');
    linkedom = require('linkedom');
  } catch (e) {
    emit({ results: [], harness_error: 'setup failed: ' + String((e && e.message) || e) });
    return;
  }
  const page = html.replace('</head>', () => '<style>' + css + '</style></head>');
  const results = [];
  for (const item of inputs) {
    const id = item && item.id;
    try {
      const actual = runCase(linkedom, js, page, (item && item.input) || {});
      results.push({ id, actual });
    } catch (e) {
      results.push({ id, error: String((e && e.message) || e) });
    }
  }
  emit({ results });
}

main();
